  --accent: #c2410c;
  --accent-hover: #9a330a;
  --sale: #b91c1c;
  --focus: #2563eb;
  --radius: 4px;
  --radius-lg: 12px;
  --max: 1280px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
