* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--ink);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
button { font: inherit; cursor: pointer; }
a { color: inherit; }

/* Accessibility primitives */
.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--ink);
  color: #fff;
  padding: 12px 16px;
  z-index: 1000;
  text-decoration: none;
  font-weight: 600;
}
.skip-link:focus { left: 8px; top: 8px; outline: 3px solid var(--focus); }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Announcement bar */
.announcement {
  background: var(--ink);
  color: #fff;
  text-align: center;
  font-size: 0.85rem;
  padding: 10px 16px;
  letter-spacing: 0.02em;
}
.announcement strong { font-weight: 600; }

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 248, 245, 0.92);
  backdrop-filter: saturate(140%) blur(8px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  max-width: var(--max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 18px 24px;
}
.brand {
  font-family: 'Fraunces', Georgia, serif;
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  text-decoration: none;
  color: var(--ink);
}
.primary-nav ul {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  gap: 28px;
  justify-content: center;
}
.primary-nav a {
  text-decoration: none;
  color: var(--ink-soft);
  font-weight: 500;
  font-size: 0.95rem;
  padding: 6px 2px;
  border-bottom: 2px solid transparent;
  transition: color .15s, border-color .15s;
}
.primary-nav a:hover { color: var(--ink); border-bottom-color: var(--ink); }
.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  background: transparent;
  border: 1px solid transparent;
  color: var(--ink);
  width: 40px; height: 40px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  transition: background .15s;
}
.icon-btn:hover { background: rgba(0,0,0,0.06); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  min-width: 18px; height: 18px;
  border-radius: 999px;
  padding: 0 5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 24px;
  border-radius: var(--radius);
  border: 1px solid var(--ink);
  background: var(--ink);
  color: #fff;
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  transition: background .15s, border-color .15s, color .15s, transform .1s;
}
.btn:hover { background: #000; }
.btn:active { transform: translateY(1px); }
.btn--ghost {
  background: transparent;
  color: var(--ink);
}
.btn--ghost:hover { background: var(--ink); color: #fff; }
.btn--accent {
  background: var(--accent);
  border-color: var(--accent);
}
.btn--accent:hover { background: var(--accent-hover); border-color: var(--accent-hover); }

/* Hero */
.hero {
  max-width: var(--max);
  margin: 0 auto;
  padding: 48px 24px 64px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.hero-eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 0.78rem;
  color: var(--muted);
  font-weight: 600;
  margin: 0 0 16px;
}
.hero h1 {
  font-family: 'Fraunces', Georgia, serif;
  font-weight: 600;
  font-size: clamp(2.4rem, 5vw, 4rem);
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin: 0 0 20px;
}
.hero h1 em { font-style: italic; color: var(--accent); }
.hero p.lede {
  color: var(--ink-soft);
  font-size: 1.1rem;
  max-width: 46ch;
  margin: 0 0 28px;
}
.hero-ctas { display: flex; flex-wrap: wrap; gap: 12px; }
.hero-image {
  position: relative;
  aspect-ratio: 4 / 5;
  background: linear-gradient(135deg, #e8dfd2, #d6c5a8);
  border-radius: var(--radius-lg);
  overflow: hidden;
}
.hero-image img {
  width: 100%; height: 100%;
  object-fit: cover;
}
.hero-badge {
  position: absolute;
  bottom: 20px; left: 20px;
  background: var(--surface);
  padding: 14px 18px;
  border-radius: var(--radius);
  box-shadow: var(--shadow-md);
  font-size: 0.85rem;
}
.hero-badge strong { display: block; font-size: 1.1rem; }

/* Section heading */
.section {
  max-width: var(--max);
  margin: 0 auto;
  padding: 64px 24px;
}
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-family: 'Fraunces', Georgia, serif;
  font-weight: 600;
  font-size: clamp(1.75rem, 3vw, 2.4rem);
  letter-spacing: -0.01em;
  margin: 0 0 6px;
}
.section-head p {
  color: var(--muted);
  margin: 0;
  max-width: 50ch;
}
.section-head a.see-all {
  color: var(--ink);
  font-weight: 600;
  text-decoration: none;
  border-bottom: 1px solid var(--ink);
  padding-bottom: 2px;
  font-size: 0.9rem;
}
.section-head a.see-all:hover { color: var(--accent); border-bottom-color: var(--accent); }

/* Category chips */
.chips {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 28px;
}
.chip {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--ink);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 0.9rem;
  font-weight: 500;
  transition: all .15s;
}
.chip:hover { border-color: var(--ink); }
.chip[aria-pressed="true"] {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

/* Product grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px 24px;
}
.product-card {
  background: transparent;
  border: 0;
  padding: 0;
  text-align: left;
  display: flex;
  flex-direction: column;
}
.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  background: #ece6dc;
  border-radius: var(--radius-lg);
  overflow: hidden;
  margin-bottom: 14px;
}
.product-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s ease;
}
.product-card:hover .product-media img,
.product-card:focus-within .product-media img {
  transform: scale(1.04);
}
.product-tag {
  position: absolute;
  top: 12px; left: 12px;
  background: var(--surface);
  color: var(--ink);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 4px;
}
.product-tag--sale { background: var(--sale); color: #fff; }
.wishlist-btn {
  position: absolute;
  top: 12px; right: 12px;
  width: 36px; height: 36px;
  border-radius: 999px;
  background: var(--surface);
  border: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  transition: background .15s;
}
.wishlist-btn:hover { background: #fff; }
.wishlist-btn svg { width: 18px; height: 18px; }
.wishlist-btn[aria-pressed="true"] svg { fill: var(--sale); stroke: var(--sale); }
.product-info { display: flex; flex-direction: column; gap: 4px; }
.product-cat {
  font-size: 0.75rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 600;
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  color: var(--ink);
}
.product-name a { text-decoration: none; }
.product-name a:hover { color: var(--accent); }
.product-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 4px;
}
.price-now { font-weight: 600; color: var(--ink); }
.price-was { color: var(--muted); text-decoration: line-through; font-size: 0.9rem; }
.price-save { color: var(--sale); font-size: 0.8rem; font-weight: 600; }
.product-rating {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.85rem;
  color: var(--ink-soft);
  margin-top: 4px;
}
.product-rating svg { width: 14px; height: 14px; fill: #d97706; }

/* Deals strip */
.deals {
  background: linear-gradient(180deg, #fff 0%, #f5f0e8 100%);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 64px 0;
}
.deals .section { padding-top: 0; padding-bottom: 0; }
.deals-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 20px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: end;
  padding: 28px;
  color: #fff;
  text-decoration: none;
  isolation: isolate;
}
.deal-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0.1) 30%, rgba(0,0,0,0.7) 100%);
  z-index: -1;
}
.deal-card img {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  z-index: -2;
  transition: transform .4s;
}
.deal-card:hover img { transform: scale(1.03); }
.deal-tag {
  background: #fff;
  color: var(--sale);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 4px;
  align-self: start;
  margin-bottom: 12px;
}
.deal-card h3 {
  font-family: 'Fraunces', Georgia, serif;
  font-size: 1.6rem;
  font-weight: 600;
  margin: 0 0 6px;
  line-height: 1.15;
}
.deal-card p {
  margin: 0 0 16px;
  font-size: 0.95rem;
  opacity: 0.9;
}
.deal-card .deal-cta {
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.9rem;
}
.deal-card:hover .deal-cta { text-decoration: underline; }
.deal-card--featured { min-height: 380px; }
.deal-card--featured h3 { font-size: 2rem; }

/* Editorial */
.editorial {
  padding: 80px 24px;
  background: var(--surface);
  border-top: 1px solid var(--line);
}
.editorial-inner {
  max-width: var(--max);
  margin: 0 auto;
}
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}
.article-card {
  display: flex;
  flex-direction: column;
}
.article-media {
  aspect-ratio: 16 / 10;
  border-radius: var(--radius-lg);
  overflow: hidden;
  margin-bottom: 18px;
  background: #ece6dc;
}
.article-media img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s;
}
.article-card a:hover .article-media img { transform: scale(1.03); }
.article-meta {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  font-weight: 600;
  margin-bottom: 8px;
}
.article-title {
  font-family: 'Fraunces', Georgia, serif;
  font-size: 1.3rem;
  font-weight: 600;
  line-height: 1.25;
  margin: 0 0 8px;
}
.article-title a { text-decoration: none; }
.article-title a:hover { color: var(--accent); }
.article-excerpt {
  color: var(--ink-soft);
  margin: 0;
  font-size: 0.95rem;
}

/* Newsletter */
.newsletter {
  max-width: var(--max);
  margin: 0 auto;
  padding: 80px 24px;
}
.newsletter-card {
  background: var(--ink);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 64px 48px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.newsletter-card h2 {
  font-family: 'Fraunces', Georgia, serif;
  font-size: clamp(1.75rem, 3vw, 2.4rem);
  font-weight: 600;
  margin: 0 0 12px;
  letter-spacing: -0.01em;
}
.newsletter-card p {
  margin: 0;
  opacity: 0.85;
}
.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.newsletter-row {
  display: flex;
  gap: 8px;
}
.newsletter-input {
  flex: 1;
  padding: 14px 16px;
  border-radius: var(--radius);
  border: 1px solid rgba(255,255,255,0.25);
  background: rgba(255,255,255,0.08);
  color: #fff;
  font-size: 1rem;
  font-family: inherit;
}
.newsletter-input::placeholder { color: rgba(255,255,255,0.55); }
.newsletter-input:focus { outline: 2px solid #fff; outline-offset: 2px; background: rgba(255,255,255,0.14); }
.newsletter-note { font-size: 0.85rem; opacity: 0.7; margin: 0; }
.newsletter-success {
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.25);
  padding: 14px 16px;
  border-radius: var(--radius);
}

/* Footer */
.site-footer {
  background: #f0ebe3;
  border-top: 1px solid var(--line);
  padding: 56px 24px 24px;
  color: var(--ink-soft);
  font-size: 0.9rem;
}
.footer-inner {
  max-width: var(--max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  padding-bottom: 40px;
  border-bottom: 1px solid var(--line);
}
.footer-brand .brand { color: var(--ink); display: inline-block; margin-bottom: 12px; }
.footer-col h3 {
  color: var(--ink);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  margin: 0 0 14px;
}
.footer-col ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }
.footer-col a { text-decoration: none; color: var(--ink-soft); }
.footer-col a:hover { color: var(--ink); text-decoration: underline; }
.footer-bottom {
  max-width: var(--max);
  margin: 0 auto;
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 0.82rem;
  color: var(--muted);
}

/* Trust bar */
.trust-bar {
  border-top: 1px solid var(--line);
  background: var(--surface);
}
.trust-inner {
  max-width: var(--max);
  margin: 0 auto;
  padding: 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.trust-item {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.9rem;
}
.trust-item svg { width: 24px; height: 24px; flex-shrink: 0; color: var(--accent); }
.trust-item strong { display: block; color: var(--ink); }
.trust-item span { color: var(--muted); font-size: 0.82rem; }

/* Responsive */
@media (max-width: 960px) {
  .hero { grid-template-columns: 1fr; padding: 32px 20px 40px; gap: 32px; }
  .hero-image { aspect-ratio: 4 / 3; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .newsletter-card { grid-template-columns: 1fr; padding: 40px 28px; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
  .trust-inner { grid-template-columns: repeat(2, 1fr); }
  .primary-nav { display: none; }
  .header-inner { grid-template-columns: 1fr auto; }
}
@media (max-width: 520px) {
  .product-grid { grid-template-columns: 1fr 1fr; gap: 20px 14px; }
  .footer-inner { grid-template-columns: 1fr; }
  .newsletter-row { flex-direction: column; }
  .section { padding: 48px 20px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
