.newsletter-note { font-size: 0.85rem; opacity: 0.7; margin: 0; }
.newsletter-success {
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.25);
  padding: 14px 16px;
  border-radius: var(--radius);
}

/* Footer */
.site-footer {
  background: #f0ebe3;
  border-top: 1px solid var(--line);
  padding: 56px 24px 24px;
  color: var(--ink-soft);
  font-size: 0.9rem;
}
.footer-inner {
  max-width: var(--max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  padding-bottom: 40px;
  border-bottom: 1px solid var(--line);
}
.footer-brand .brand { color: var(--ink); display: inline-block; margin-bottom: 12px; }
.footer-col h3 {
  color: var(--ink);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  margin: 0 0 14px;
}
.footer-col ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }
.footer-col a { text-decoration: none; color: var(--ink-soft); }
.footer-col a:hover { color: var(--ink); text-decoration: underline; }
.footer-bottom {
  max-width: var(--max);
  margin: 0 auto;
  padding-top: 20px;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 0.82rem;
  color: var(--muted);
}

/* Trust bar */
.trust-bar {
  border-top: 1px solid var(--line);
  background: var(--surface);
}
.trust-inner {
  max-width: var(--max);
  margin: 0 auto;
  padding: 24px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.trust-item {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.9rem;
}
.trust-item svg { width: 24px; height: 24px; flex-shrink: 0; color: var(--accent); }
.trust-item strong { display: block; color: var(--ink); }
.trust-item span { color: var(--muted); font-size: 0.82rem; }

/* Responsive */
@media (max-width: 960px) {
  .hero { grid-template-columns: 1fr; padding: 32px 20px 40px; gap: 32px; }
  .hero-image { aspect-ratio: 4 / 3; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .newsletter-card { grid-template-columns: 1fr; padding: 40px 28px; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
  .trust-inner { grid-template-columns: repeat(2, 1fr); }
  .primary-nav { display: none; }
  .header-inner { grid-template-columns: 1fr auto; }
}
@media (max-width: 520px) {
  .product-grid { grid-template-columns: 1fr 1fr; gap: 20px 14px; }
  .footer-inner { grid-template-columns: 1fr; }
  .newsletter-row { flex-direction: column; }
  .section { padding: 48px 20px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

