const { useState, useMemo, useEffect } = React;

/* ---------- Data ---------- */

const PRODUCTS = [
  { id: 'p1', name: 'Linen Throw Blanket', category: 'Home', tag: 'New', price: 89, image: 'https://images.unsplash.com/photo-1584100936595-c0654b55a2e2?w=600&q=80' },
  { id: 'p2', name: 'Ceramic Pour-Over Set', category: 'Kitchen', tag: 'Bestseller', price: 64, image: 'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=600&q=80' },
  { id: 'p3', name: 'Merino Crewneck', category: 'Apparel', tag: 'Sale', price: 78, was: 120, image: 'https://images.unsplash.com/photo-1591047139829-d91aecb6caea?w=600&q=80' },
  { id: 'p4', name: 'Walnut Desk Organizer', category: 'Office', tag: 'New', price: 54, image: 'https://images.unsplash.com/photo-1611532736597-de2d4265fba3?w=600&q=80' },
  { id: 'p5', name: 'Brass Table Lamp', category: 'Home', price: 145, image: 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?w=600&q=80' },
  { id: 'p6', name: 'Cotton Canvas Tote', category: 'Apparel', tag: 'Sale', price: 32, was: 48, image: 'https://images.unsplash.com/photo-1591561954557-26941169b49e?w=600&q=80' },
  { id: 'p7', name: 'Stoneware Mug Set', category: 'Kitchen', price: 42, image: 'https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?w=600&q=80' },
  { id: 'p8', name: 'Leather Notebook', category: 'Office', tag: 'Bestseller', price: 38, image: 'https://images.unsplash.com/photo-1531346878377-a5be20888e57?w=600&q=80' },
];

const CATEGORIES = ['All', 'Home', 'Kitchen', 'Apparel', 'Office'];

const DEALS = [
  {
    id: 'd1',
    title: 'Fall Refresh — Up to 40% off',
    blurb: 'Cozy textiles, warm tones, and seasonal essentials.',
    tag: 'Limited time',
    image: 'https://images.unsplash.com/photo-1493663284031-b7e3aefcae8e?w=900&q=80',
    featured: true,
  },
  {
    id: 'd2',
    title: 'Kitchen Edit',
    blurb: 'Save 25% on cookware & ceramics.',
    tag: '25% off',
    image: 'https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=700&q=80',
  },
  {
    id: 'd3',
    title: 'Workspace Essentials',
    blurb: 'Bundle and save on desk staples.',
    tag: 'Bundle deal',
    image: 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=700&q=80',
  },
];

const ARTICLES = [
  {
    id: 'a1',
    category: 'Journal',
    title: 'A Slower Morning: Building Rituals That Last',
    excerpt: 'How small, intentional objects can reshape the way your day begins.',
    image: 'https://images.unsplash.com/photo-1495197359483-d092478c170a?w=800&q=80',
    readTime: '4 min read',
  },
  {
    id: 'a2',
    category: 'Inside Maren',
    title: 'Meet the Makers: Our Ceramic Studio in Porto',
    excerpt: 'A look inside the family-run workshop crafting our signature stoneware.',
    image: 'https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?w=800&q=80',
    readTime: '6 min read',
  },
  {
    id: 'a3',
    category: 'Guide',
    title: 'Layering Linens for the In-Between Season',
    excerpt: 'Three easy ways to refresh your bed and sofa as temperatures shift.',
    image: 'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?w=800&q=80',
    readTime: '3 min read',
  },
];

/* ---------- Icons (decorative — aria-hidden) ---------- */

const Icon = ({ name, ...rest }) => {
  const props = { width: 20, height: 20, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', strokeWidth: 1.8, strokeLinecap: 'round', strokeLinejoin: 'round', 'aria-hidden': 'true', focusable: 'false', ...rest };
  switch (name) {
    case 'search': return <svg {...props}><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>;
    case 'user': return <svg {...props}><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4.4 3.6-8 8-8s8 3.6 8 8"/></svg>;
    case 'heart': return <svg {...props}><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.6l-1-1a5.5 5.5 0 0 0-7.8 7.8l1 1L12 21l7.8-7.8 1-1a5.5 5.5 0 0 0 0-7.6Z"/></svg>;
    case 'bag': return <svg {...props}><path d="M6 7h12l-1 13H7L6 7Z"/><path d="M9 7a3 3 0 1 1 6 0"/></svg>;
    case 'star': return <svg {...props} stroke="none"><path d="m12 2 3 7 7 .6-5.3 4.6L18 21l-6-3.7L6 21l1.3-6.8L2 9.6 9 9l3-7Z"/></svg>;
    case 'arrow': return <svg {...props}><path d="M5 12h14"/><path d="m13 6 6 6-6 6"/></svg>;
    case 'truck': return <svg {...props}><path d="M3 7h11v8H3z"/><path d="M14 10h4l3 3v2h-7"/><circle cx="7" cy="17" r="2"/><circle cx="17" cy="17" r="2"/></svg>;
    case 'return': return <svg {...props}><path d="M3 12a9 9 0 1 0 3-6.7"/><path d="M3 4v5h5"/></svg>;
    case 'shield': return <svg {...props}><path d="M12 3 4 6v6c0 5 3.5 8.5 8 9 4.5-.5 8-4 8-9V6l-8-3Z"/><path d="m9 12 2 2 4-4"/></svg>;
    case 'leaf': return <svg {...props}><path d="M5 19c0-8 6-14 14-14 0 8-6 14-14 14Z"/><path d="M5 19c4-4 8-6 14-14"/></svg>;
    default: return null;
  }
};

/* ---------- Components ---------- */

const AnnouncementBar = () => (
  <div className="announcement" role="region" aria-label="Promotional announcement">
    <strong>Free shipping</strong> on orders over $75 &middot; Use code <strong>FALL10</strong> for 10% off
  </div>
);

const Header = ({ cartCount, wishlistCount }) => (
  <header className="site-header">
    <div className="header-inner">
      <a href="#" className="brand" aria-label="Maren home">Maren.</a>
      <nav className="primary-nav" aria-label="Primary">
        <ul>
          <li><a href="#shop">Shop</a></li>
          <li><a href="#new">New Arrivals</a></li>
          <li><a href="#deals">Sale</a></li>
          <li><a href="#editorial">Journal</a></li>
          <li><a href="#about">About</a></li>
        </ul>
      </nav>
      <div className="header-actions">
        <button className="icon-btn" aria-label="Search">
          <Icon name="search" />
        </button>
        <button className="icon-btn" aria-label="Account">
          <Icon name="user" />
        </button>
        <button className="icon-btn" aria-label={`Wishlist, ${wishlistCount} items`}>
          <Icon name="heart" />
          {wishlistCount > 0 && <span className="cart-count" aria-hidden="true">{wishlistCount}</span>}
        </button>
        <button className="icon-btn" aria-label={`Cart, ${cartCount} items`}>
          <Icon name="bag" />
          {cartCount > 0 && <span className="cart-count" aria-hidden="true">{cartCount}</span>}
        </button>
      </div>
    </div>
  </header>
);

const Hero = () => (
  <section className="hero" aria-labelledby="hero-title">
    <div>
      <p className="hero-eyebrow">Fall Collection 2026</p>
      <h1 id="hero-title">Considered objects for an <em>unhurried</em> life.</h1>
      <p className="lede">Discover our latest range of home, kitchen, and wardrobe essentials — designed to last and made with care.</p>
      <div className="hero-ctas">
        <a href="#shop" className="btn btn--accent">Shop the collection <Icon name="arrow" width="16" height="16" /></a>
        <a href="#editorial" className="btn btn--ghost">Read our story</a>
      </div>
    </div>
    <div className="hero-image">
      <img
        src="https://images.unsplash.com/photo-1505691938895-1758d7feb511?w=900&q=80"
        alt="A softly lit interior featuring a linen-draped bed and ceramic vessels in warm autumn tones."
        loading="eager"
      />
      <div className="hero-badge" aria-hidden="true">
        <strong>4.9 / 5</strong>
        <span>Loved by 12,000+ customers</span>
      </div>
    </div>
  </section>
);

const Rating = ({ value, count }) => (
  <div className="product-rating" aria-label={`Rated ${value} out of 5 from ${count} reviews`}>
    <Icon name="star" />
    <span>{value.toFixed(1)} <span aria-hidden="true">({count})</span></span>
  </div>
);

const ProductCard = ({ product, isWishlisted, onWishlist, onAdd }) => {
  const save = product.was ? Math.round(((product.was - product.price) / product.was) * 100) : 0;
  const headingId = `prod-${product.id}-name`;
  return (
    <article className="product-card" aria-labelledby={headingId}>
      <div className="product-media">
        <img src={product.image} alt={product.name} loading="lazy" />
        {product.tag && (
          <span className={`product-tag ${product.tag === 'Sale' ? 'product-tag--sale' : ''}`}>{product.tag}</span>
        )}
        <button
          className="wishlist-btn"
          aria-label={isWishlisted ? `Remove ${product.name} from wishlist` : `Add ${product.name} to wishlist`}
          aria-pressed={isWishlisted}
          onClick={() => onWishlist(product.id)}
        >
          <Icon name="heart" />
        </button>
      </div>
      <div className="product-info">
        <span className="product-cat">{product.category}</span>
        <h3 className="product-name" id={headingId}>
          <a href={`#product-${product.id}`}>{product.name}</a>
        </h3>
        <Rating value={4.5 + (product.id.charCodeAt(1) % 5) / 10} count={40 + (product.id.charCodeAt(1) % 7) * 12} />
        <div className="product-price">
          <span className="price-now">${product.price}</span>
          {product.was && <span className="price-was" aria-label={`Was $${product.was}`}>${product.was}</span>}
          {save > 0 && <span className="price-save">Save {save}%</span>}
        </div>
        <button
          className="btn btn--ghost"
          style={{ marginTop: 10, padding: '10px 14px', fontSize: '0.85rem' }}
          onClick={() => onAdd(product.id)}
          aria-label={`Add ${product.name} to cart`}
        >
          Add to cart
        </button>
      </div>
    </article>
  );
};

const FeaturedProducts = ({ wishlist, onWishlist, onAdd }) => {
  const [active, setActive] = useState('All');
  const filtered = useMemo(
    () => active === 'All' ? PRODUCTS : PRODUCTS.filter(p => p.category === active),
    [active]
  );
  return (
    <section className="section" id="shop" aria-labelledby="featured-heading">
      <div className="section-head">
        <div>
          <h2 id="featured-heading">Featured Products</h2>
          <p>Hand-picked favorites from our newest collection.</p>
        </div>
        <a href="#all" className="see-all">View all products</a>
      </div>
      <div className="chips" role="group" aria-label="Filter products by category">
        {CATEGORIES.map(c => (
          <button
            key={c}
            className="chip"
            aria-pressed={active === c}
            onClick={() => setActive(c)}
          >
            {c}
          </button>
        ))}
      </div>
      <div className="product-grid" role="list">
        {filtered.map(p => (
          <div role="listitem" key={p.id}>
            <ProductCard
              product={p}
              isWishlisted={wishlist.includes(p.id)}
              onWishlist={onWishlist}
              onAdd={onAdd}
            />
          </div>
        ))}
      </div>
    </section>
  );
};

const Deals = () => (
  <section className="deals" id="deals" aria-labelledby="deals-heading">
    <div className="section">
      <div className="section-head">
        <div>
          <h2 id="deals-heading">This Week's Deals</h2>
          <p>Seasonal markdowns and limited-time offers.</p>
        </div>
        <a href="#sale" className="see-all">Shop all sale</a>
      </div>
      <div className="deals-grid">
        {DEALS.map((d, i) => (
          <a
            key={d.id}
            href={`#${d.id}`}
            className={`deal-card ${i === 0 ? 'deal-card--featured' : ''}`}
            style={{ gridRow: i === 0 ? 'span 2' : 'auto' }}
            aria-label={`${d.title}. ${d.blurb}`}
          >
            <img src={d.image} alt="" loading="lazy" />
            <span className="deal-tag">{d.tag}</span>
            <h3>{d.title}</h3>
            <p>{d.blurb}</p>
            <span className="deal-cta" aria-hidden="true">Shop now <Icon name="arrow" width="14" height="14" /></span>
          </a>
        ))}
      </div>
    </div>
  </section>
);

const Editorial = () => (
  <section className="editorial" id="editorial" aria-labelledby="editorial-heading">
    <div className="editorial-inner">
      <div className="section-head">
        <div>
          <h2 id="editorial-heading">From the Journal</h2>
          <p>Stories, guides, and inspiration from the Maren team.</p>
        </div>
        <a href="#journal" className="see-all">All stories</a>
      </div>
      <div className="editorial-grid">
        {ARTICLES.map(a => (
          <article className="article-card" key={a.id}>
            <a href={`#${a.id}`} aria-labelledby={`art-${a.id}`}>
              <div className="article-media">
                <img src={a.image} alt="" loading="lazy" />
              </div>
            </a>
            <p className="article-meta">{a.category} &middot; {a.readTime}</p>
            <h3 className="article-title" id={`art-${a.id}`}>
              <a href={`#${a.id}`}>{a.title}</a>
            </h3>
            <p className="article-excerpt">{a.excerpt}</p>
          </article>
        ))}
      </div>
    </div>
  </section>
);

const TrustBar = () => {
  const items = [
    { icon: 'truck', title: 'Free shipping', sub: 'On orders over $75' },
    { icon: 'return', title: '30-day returns', sub: 'No-fuss policy' },
    { icon: 'shield', title: 'Secure checkout', sub: 'Encrypted payments' },
    { icon: 'leaf', title: 'Made to last', sub: 'Sustainable materials' },
  ];
  return (
    <section className="trust-bar" aria-label="Customer benefits">
      <div className="trust-inner">
        {items.map(it => (
          <div className="trust-item" key={it.title}>
            <Icon name={it.icon} />
            <div>
              <strong>{it.title}</strong>
              <span>{it.sub}</span>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

const Newsletter = () => {
  const [email, setEmail] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState('');
  const onSubmit = (e) => {
    e.preventDefault();
    if (!/^\S+@\S+\.\S+$/.test(email)) {
      setError('Please enter a valid email address.');
      return;
    }
    setError('');
    setSubmitted(true);
  };
  return (
    <section className="newsletter" aria-labelledby="news-heading">
      <div className="newsletter-card">
        <div>
          <h2 id="news-heading">Join the Maren list.</h2>
          <p>Early access to new arrivals, member-only offers, and the occasional good read. No spam.</p>
        </div>
        {submitted ? (
          <div className="newsletter-success" role="status" aria-live="polite">
            <strong>Thanks for subscribing!</strong>
            <p style={{ margin: '4px 0 0', opacity: 0.85 }}>Check your inbox for a welcome message.</p>
          </div>
        ) : (
          <form className="newsletter-form" onSubmit={onSubmit} noValidate>
            <label htmlFor="news-email" className="sr-only">Email address</label>
            <div className="newsletter-row">
              <input
                id="news-email"
                type="email"
                className="newsletter-input"
                placeholder="you@example.com"
                value={email}
                onChange={e => setEmail(e.target.value)}
                aria-invalid={!!error}
                aria-describedby={error ? 'news-error' : 'news-note'}
                required
              />
              <button type="submit" className="btn" style={{ background: '#fff', color: '#1a1a1a', borderColor: '#fff' }}>
                Subscribe
              </button>
            </div>
            {error
              ? <p id="news-error" className="newsletter-note" role="alert" style={{ color: '#fca5a5' }}>{error}</p>
              : <p id="news-note" className="newsletter-note">By subscribing you agree to our privacy policy.</p>
            }
          </form>
        )}
      </div>
    </section>
  );
};

const Footer = () => (
  <footer className="site-footer" aria-labelledby="footer-heading">
    <h2 id="footer-heading" className="sr-only">Site footer</h2>
    <div className="footer-inner">
      <div className="footer-brand">
        <a href="#" className="brand">Maren.</a>
        <p style={{ maxWidth: '36ch', margin: 0 }}>Considered objects for the home, kitchen, and wardrobe — designed in Lisbon, made worldwide.</p>
      </div>
      <div className="footer-col">
        <h3>Shop</h3>
        <ul>
          <li><a href="#">New arrivals</a></li>
          <li><a href="#">Best sellers</a></li>
          <li><a href="#">Sale</a></li>
          <li><a href="#">Gift cards</a></li>
        </ul>
      </div>
      <div className="footer-col">
        <h3>Help</h3>
        <ul>
          <li><a href="#">Shipping</a></li>
          <li><a href="#">Returns</a></li>
          <li><a href="#">Contact us</a></li>
          <li><a href="#">Size guide</a></li>
        </ul>
      </div>
      <div className="footer-col">
        <h3>Company</h3>
        <ul>
          <li><a href="#">About</a></li>
          <li><a href="#">Sustainability</a></li>
          <li><a href="#">Journal</a></li>
          <li><a href="#">Careers</a></li>
        </ul>
      </div>
    </div>
    <div className="footer-bottom">
      <span>&copy; 2026 Maren Studio. All rights reserved.</span>
      <span><a href="#">Privacy</a> &middot; <a href="#">Terms</a> &middot; <a href="#">Accessibility</a></span>
    </div>
  </footer>
);

/* ---------- App ---------- */

const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState([]);

  const addToCart = (id) => setCart(c => [...c, id]);
  const toggleWishlist = (id) =>
    setWishlist(w => w.includes(id) ? w.filter(x => x !== id) : [...w, id]);

  return (
    <>
      <AnnouncementBar />
      <Header cartCount={cart.length} wishlistCount={wishlist.length} />
      <main id="main">
        <Hero />
        <FeaturedProducts wishlist={wishlist} onWishlist={toggleWishlist} onAdd={addToCart} />
        <Deals />
        <TrustBar />
        <Editorial />
        <Newsletter />
      </main>
      <Footer />
    </>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
